/**
 * A tool invocation shown as one expandable row (`design/components/tool-call.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/tool-call.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import * as zag from '@zag-js/collapsible'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  Spread,
  agentMember,
  classes,
  derived,
  elementRef,
  measured,
  mergeParts,
  mountEffect,
  normalizeProps,
  setup,
  uniqueId,
  useDirection,
  useMachine,
  useMember,
  type IconProps,
  type IconRole,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/ai/tool-call.module.css'
import { CodeBlock, type CodeBlockProps } from '../structure/CodeBlock'
import { JsonTree, type JsonTreeProps } from '../structure/JsonTree'

export type ToolCallStatus = 'pending' | 'running' | 'done' | 'error' | 'denied' | 'approval'

export interface ToolCallMessages {
  input: string
  output: string
  status: Record<ToolCallStatus, string>
}

/** A tool invocation shown as one expandable row: the inputs it takes, by the React member's prop names. */
export interface ToolCallProps {
  defaultOpen?: boolean
  /**
   * The duration, preformatted by the app, such as "1.2s".
   */
  duration?: string
  /**
   * The tool's mark, `tool` by default, or `terminal`, `network` or `document` when the app
   * knows the kind.
   */
  icon?: IconRole
  /**
   * The arguments, rendered as JsonTree for a value or as CodeBlock for a string.
   */
  input?: unknown
  /**
   * The app's text for a failure or a refusal.
   */
  message?: string
  /**
   * All of the card's text (generic English defaults), which localized hosts replace.
   */
  messages?: ToolCallMessages
  /**
   * The tool's name as the model called it, such as `read_file` or `search_web`.
   */
  name: string
  open?: boolean
  status: 'error' | 'denied' | 'done' | 'pending' | 'running' | 'approval'
  /**
   * One line describing the call, such as the file read or the query run.
   */
  summary?: string
}

/** A tool invocation shown as one expandable row. */
@Component({
  selector: 'pm-tool-call',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Spread, CodeBlock, Icon, JsonTree],
  // prettier-ignore
  template: `<ng-template pmSlot="output" [pmSlotOf]="$"><ng-content select="[slot=output]" /></ng-template>
<div
[pmSpread]="e1()"
><!-- trigger -->
<button
[pmSpread]="e2()"
[pmRef]="trigger"
><span
[attr.class]="e3()"
><pm-icon
[name]="e4()"
size="sm"
></pm-icon></span>
<span
[attr.class]="e5()"
>{{ e6() }}</span>
@if (e7()) {<span
[attr.class]="e8()"
>{{ e9() }}</span>}
<span
[attr.class]="e10()"
>@if (e11()) {<span
[attr.class]="e12()"
>{{ e13() }}</span>}
<span
[attr.class]="e14()"
><pm-icon
[name]="e15()"
size="sm"
></pm-icon></span>
<span
[attr.class]="e16()"
>{{ e17() }}</span>
@if (e18()) {<span
[attr.class]="e19()"
><pm-icon
name="down"
size="sm"
></pm-icon></span>}</span></button>
@if (e18()) {<!-- content -->
<div
[pmSpread]="e20()"
><div
[attr.class]="e21()"
>@if (e22()) {<div
[attr.class]="e23()"
><span
[attr.class]="e24()"
>{{ e25() }}</span>
@if (e26()) {<pm-code-block
[label]="e27()"
>{{ e28() }}</pm-code-block>} @else {<pm-json-tree
[data]="e29()"
[label]="e30()"
[defaultDepth]="e31()"
></pm-json-tree>}</div>}
@if (e32()) {<div
[attr.class]="e33()"
><span
[attr.class]="e34()"
>{{ e35() }}</span>
<ng-container [pmSlotOutlet]="'output'" [pmSlotOf]="$" /></div>}
@if (e36()) {<p
[attr.class]="e37()"
>{{ e38() }}</p>}</div></div>}</div>`,
})
export class ToolCall {
  readonly defaultOpen = input<
    Exclude<ToolCallProps['defaultOpen'], undefined>,
    ToolCallProps['defaultOpen']
  >(false, {
    transform: (value: ToolCallProps['defaultOpen']) => (value === undefined ? false : value),
  })
  /**
   * The duration, preformatted by the app, such as "1.2s".
   */
  readonly duration = input<ToolCallProps['duration']>(undefined)
  /**
   * The tool's mark, `tool` by default, or `terminal`, `network` or `document` when the app
   * knows the kind.
   */
  readonly icon = input<Exclude<ToolCallProps['icon'], undefined>, ToolCallProps['icon']>('tool', {
    transform: (value: ToolCallProps['icon']) => (value === undefined ? 'tool' : value),
  })
  /**
   * The arguments, rendered as JsonTree for a value or as CodeBlock for a string.
   */
  readonly input = input<ToolCallProps['input']>(undefined)
  /**
   * The app's text for a failure or a refusal.
   */
  readonly message = input<ToolCallProps['message']>(undefined)
  /**
   * All of the card's text (generic English defaults), which localized hosts replace.
   */
  readonly messages = input<
    Exclude<ToolCallProps['messages'], undefined>,
    ToolCallProps['messages']
  >(
    (() => ({
      input: 'Input',
      output: 'Output',
      status: {
        pending: 'Pending',
        running: 'Running',
        done: 'Done',
        error: 'Failed',
        denied: 'Denied',
        approval: 'Awaiting approval',
      },
    }))(),
    {
      transform: (value: ToolCallProps['messages']) =>
        value === undefined
          ? (() => ({
              input: 'Input',
              output: 'Output',
              status: {
                pending: 'Pending',
                running: 'Running',
                done: 'Done',
                error: 'Failed',
                denied: 'Denied',
                approval: 'Awaiting approval',
              },
            }))()
          : value,
    },
  )
  /**
   * The tool's name as the model called it, such as `read_file` or `search_web`.
   */
  readonly name = input.required<ToolCallProps['name']>()
  readonly open = input<ToolCallProps['open']>(undefined)
  readonly status = input.required<ToolCallProps['status']>()
  /**
   * One line describing the call, such as the file read or the query run.
   */
  readonly summary = input<ToolCallProps['summary']>(undefined)
  readonly onOpenChange = output<boolean>({ alias: 'openChange' })
  protected readonly $ = useMember({
    events: ['openChange'],
    props: {
      defaultOpen: () => this.defaultOpen(),
      duration: () => this.duration(),
      icon: () => this.icon(),
      input: () => this.input(),
      message: () => this.message(),
      messages: () => this.messages(),
      name: () => this.name(),
      open: () => this.open(),
      status: () => this.status(),
      summary: () => this.summary(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly uid = uniqueId()
  protected readonly trigger = elementRef<HTMLElement>()
  protected readonly running = derived(() => this.$p.status === 'running')
  protected readonly hasBody = measured(
    () =>
      this.$p.input !== undefined ||
      Boolean(this.$.filled('output')) ||
      this.$p.message !== undefined,
  )
  protected readonly statusIcon = derived(
    () =>
      (
        ({
          pending: 'time',
          running: 'loading',
          done: 'success',
          error: 'error',
          denied: 'denied',
          approval: 'help',
        }) as const
      )[this.$p.status],
  )
  protected readonly documentDirection = useDirection(() => this.trigger.value)
  protected readonly service: { readonly value: zag.Service } = setup(() =>
    useMachine(
      zag.machine,
      () =>
        ({
          id: this.uid,
          dir: this.documentDirection(),
          open: this.$p.open,
          defaultOpen: this.$p.defaultOpen,
          disabled: !this.hasBody.value,
          onOpenChange: (details) => {
            this.$.emit(this.onOpenChange, 'onOpenChange', details.open)
          },
        }) as Partial<zag.Props>,
    ),
  )
  protected readonly api: { readonly value: ReturnType<typeof zag.connect> } = derived(() =>
    zag.connect(this.service.value, normalizeProps),
  )
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return mergeParts(this.api.value.getRootProps(), {
      class: styles.card,
      'data-status': this.$p.status,
      'aria-busy': this.running.value ? true : undefined,
      'data-member': 'tool-call',
    })
  }

  protected e2() {
    return mergeParts(this.api.value.getTriggerProps(), {
      class: styles.trigger,
      disabled: !this.hasBody.value,
    })
  }

  protected e3() {
    return styles.mark
  }

  protected e4(): IconProps['name'] {
    return this.$p.icon
  }

  protected e5() {
    return styles.name
  }

  protected e6() {
    return this.$p.name
  }

  protected e7() {
    return this.$p.summary !== undefined
  }

  protected e8() {
    if (!(this.$p.summary !== undefined)) return undefined as never
    return styles.summary
  }

  protected e9() {
    if (!(this.$p.summary !== undefined)) return undefined as never
    return this.$p.summary
  }

  protected e10() {
    return styles.trailing
  }

  protected e11() {
    return this.$p.duration !== undefined
  }

  protected e12() {
    if (!(this.$p.duration !== undefined)) return undefined as never
    return styles.duration
  }

  protected e13() {
    if (!(this.$p.duration !== undefined)) return undefined as never
    return this.$p.duration
  }

  protected e14() {
    return classes(styles.status, this.running.value ? styles.spinning : undefined)
  }

  protected e15(): IconProps['name'] {
    return this.statusIcon.value
  }

  protected e16() {
    return styles.reader
  }

  protected e17() {
    return this.$p.messages.status[this.$p.status]
  }

  protected e18() {
    return this.hasBody.value
  }

  protected e19() {
    if (!this.hasBody.value) return undefined as never
    return styles.chevron
  }

  protected e20() {
    if (!this.hasBody.value) return undefined as never
    return mergeParts(this.api.value.getContentProps(), {
      class: styles.content,
      style: {
        '--radix-collapsible-content-height': Object(this.api.value.getContentProps().style)[
          '--height'
        ],
      },
    })
  }

  protected e21() {
    if (!this.hasBody.value) return undefined as never
    return styles.inner
  }

  protected e22() {
    if (!this.hasBody.value) return undefined as never
    return this.$p.input !== undefined
  }

  protected e23() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    return styles.section
  }

  protected e24() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    return styles.heading
  }

  protected e25() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    return this.$p.messages.input
  }

  protected e26() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    return typeof this.$p.input === 'string'
  }

  protected e27(): CodeBlockProps['label'] {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    if (!(typeof this.$p.input === 'string')) return undefined as never
    return this.$p.messages.input
  }

  protected e28() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    if (!(typeof this.$p.input === 'string')) return undefined as never
    return this.$p.input
  }

  protected e29(): JsonTreeProps['data'] {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    if (typeof this.$p.input === 'string') return undefined as never
    return this.$p.input
  }

  protected e30(): JsonTreeProps['label'] {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    if (typeof this.$p.input === 'string') return undefined as never
    return this.$p.messages.input
  }

  protected e31(): JsonTreeProps['defaultDepth'] {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.input !== undefined)) return undefined as never
    if (typeof this.$p.input === 'string') return undefined as never
    return 1
  }

  protected e32() {
    if (!this.hasBody.value) return undefined as never
    return this.$.filled('output')
  }

  protected e33() {
    if (!this.hasBody.value) return undefined as never
    if (!this.$.filled('output')) return undefined as never
    return styles.section
  }

  protected e34() {
    if (!this.hasBody.value) return undefined as never
    if (!this.$.filled('output')) return undefined as never
    return styles.heading
  }

  protected e35() {
    if (!this.hasBody.value) return undefined as never
    if (!this.$.filled('output')) return undefined as never
    return this.$p.messages.output
  }

  protected e36() {
    if (!this.hasBody.value) return undefined as never
    return this.$p.message !== undefined
  }

  protected e37() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.message !== undefined)) return undefined as never
    return styles.message
  }

  protected e38() {
    if (!this.hasBody.value) return undefined as never
    if (!(this.$p.message !== undefined)) return undefined as never
    return this.$p.message
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'ToolCall',
      element: () => this.trigger.value,
      state: () => ({ status: this.$p.status, expanded: this.api.value.open }),
      actions: {
        expand: () =>
          (() => {
            if (!this.hasBody.value) throw new Error('The call has nothing to show.')
            this.api.value.setOpen(true)
          })(),
        collapse: () => this.api.value.setOpen(false),
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
